{"path":"butanol_dihedral_bomcp/reporting.py","content":"from __future__ import annotations

import json
from pathlib import Path
from typing import Any

LOG_NAME = "run.log"
JSONL_NAME = "attempts.jsonl"


class ArtifactLogger:
    def __init__(self, artifact_dir: Path) -> None:
        self.artifact_dir = artifact_dir
        self.log_path = artifact_dir / LOG_NAME
        self.jsonl_path = artifact_dir / JSONL_NAME

    def write_log(self, message: str) -> None:
        with self.log_path.open("a", encoding="utf-8") as handle:
            handle.write(message.rstrip() + "\n")

    def write_jsonl(self, payload: dict[str, Any]) -> None:
        with self.jsonl_path.open("a", encoding="utf-8") as handle:
            handle.write(json.dumps(payload, sort_keys=True) + "\n")

    def write_json(self, path: Path, payload: Any) -> None:
        path.write_text(json.dumps(payload, sort_keys=True, indent=2) + "\n", encoding="utf-8")



def emit(tag: str, message: str) -> None:
    print(f"[{tag}] {message}", flush=True)



def emit_event(message: str) -> None:
    emit("EVENT", message)



def emit_alert(message: str) -> None:
    emit("ALERT", message)



def emit_result(message: str) -> None:
    emit("RESULT", message)



def emit_heartbeat(message: str) -> None:
    emit("HEARTBEAT", message)
"}

{"path":"butanol_dihedral_bomcp/evaluate.py","content":"from __future__ import annotations

import json
import math
import time
from pathlib import Path
from typing import Any

from .constants import METHOD_BASIS_LABEL, OBJECTIVE_NAME, SCIENTIFIC_SUMMARY
from .structure import candidate_to_xyz

try:
    from grafico.containers.scientific_client import PySCFRunnerClient  # type: ignore
except ImportError:  # pragma: no cover
    PySCFRunnerClient = None  # type: ignore



def _mock_energy(parameter_values: dict[str, float]) -> float:
    angles = [math.radians(float(parameter_values[name])) for name in sorted(parameter_values)]
    return -231.0 + sum(0.004 * (1.0 - math.cos(angle)) for angle in angles) + 0.0015 * (
        1.0 - math.cos(angles[0] - angles[1])
    )



def _scientific_batch_request(
    *,
    batch_id: str,
    run_id: str,
    xyz_text: str,
    molecule_timeout_seconds: float,
) -> dict[str, Any]:
    return {
        "schema_version": 3,
        "batch_id": batch_id,
        "molecules": [
            {
                "schema_version": 3,
                "run_id": run_id,
                "summarised_user_query": SCIENTIFIC_SUMMARY,
                "identifier": {
                    "type": "xyz",
                    "value": xyz_text,
                    "charge": 0,
                    "spin_multiplicity": 1,
                    "basis_set": "def2-SVP",
                    "restricted": True,
                    "xc_functional": "PBE-D4",
                    "accelerator_policy": "auto",
                },
                "workflow": {"stop_after": "SinglePointCalculation"},
            }
        ],
        "max_parallel_molecules": 1,
        "molecule_timeout_seconds": molecule_timeout_seconds,
        "fail_fast": True,
    }



def _normalize_payload(payload: Any) -> dict[str, Any]:
    if hasattr(payload, "model_dump"):
        return payload.model_dump(mode="json")
    if isinstance(payload, dict):
        return payload
    raise TypeError(f"Unsupported payload type: {type(payload)!r}")



def evaluate_candidate(
    *,
    parameter_values: dict[str, float],
    evaluator: str,
    artifact_dir: Path,
    attempt_index: int,
    molecule_timeout_seconds: float,
) -> dict[str, Any]:
    artifact_dir.mkdir(parents=True, exist_ok=True)
    started_at = time.time()
    xyz_text = candidate_to_xyz(parameter_values)
    xyz_path = artifact_dir / f"attempt_{attempt_index:03d}.xyz"
    xyz_path.write_text(xyz_text, encoding="utf-8")

    if evaluator == "mock":
        energy = _mock_energy(parameter_values)
        return {
            "status": "ok",
            "objective_values": {OBJECTIVE_NAME: energy},
            "metadata": {
                "notes": f"Mock evaluator for {METHOD_BASIS_LABEL} BO-MCP plumbing smoke test.",
                "conditions": {
                    "evaluator": "mock",
                    "elapsed_s": round(time.time() - started_at, 3),
                    "xyz_file": str(xyz_path),
                },
            },
            "scientific_payload": {"status": "mock", "total_energy": energy},
            "scientific_result_path": None,
            "xyz_path": str(xyz_path),
        }

    if PySCFRunnerClient is None:
        return {
            "status": "failed",
            "error_type": "ImportError",
            "error": (
                "PySCFRunnerClient import failed. Run the entrypoint with the repository bootstrap "
                "and active environment, or use --evaluator mock for plumbing-only tests."
            ),
            "scientific_result_path": None,
            "xyz_path": str(xyz_path),
        }

    batch_id = f"butanol-dihedral-attempt-{attempt_index:03d}"
    request = _scientific_batch_request(
        batch_id=batch_id,
        run_id=batch_id,
        xyz_text=xyz_text,
        molecule_timeout_seconds=molecule_timeout_seconds,
    )
    try:
        client = PySCFRunnerClient.from_env()
        try:
            raw_result = client.evaluate(
                request=request,
                timeout_seconds=max(1, int(molecule_timeout_seconds)),
            )
        except ValueError as exc:
            if "timeout exceeds deployment profile limit" not in str(exc):
                raise
            raw_result = client.evaluate(request=request, timeout_seconds=None)
        payload = _normalize_payload(raw_result)
        result_path = artifact_dir / f"attempt_{attempt_index:03d}_scientific.json"
        result_path.write_text(json.dumps(payload, sort_keys=True, indent=2), encoding="utf-8")
        molecule_payload = payload["molecules"][0]["result"]
        if molecule_payload.get("status") != "ok":
            raise RuntimeError(molecule_payload.get("error") or str(molecule_payload))
        total_energy = molecule_payload.get("total_energy")
        if total_energy is None:
            raise RuntimeError(f"Scientific result missing total_energy: {molecule_payload}")
        return {
            "status": "ok",
            "objective_values": {OBJECTIVE_NAME: float(total_energy)},
            "metadata": {
                "notes": f"Single-point {METHOD_BASIS_LABEL}.",
                "conditions": {
                    "evaluator": "scientific",
                    "elapsed_s": round(time.time() - started_at, 3),
                    "xyz_file": str(xyz_path),
                    "scientific_result_file": str(result_path),
                },
            },
            "scientific_payload": molecule_payload,
            "scientific_result_path": str(result_path),
            "xyz_path": str(xyz_path),
        }
    except Exception as exc:
        return {
            "status": "failed",
            "error_type": type(exc).__name__,
            "error": str(exc),
            "scientific_result_path": None,
            "xyz_path": str(xyz_path),
        }
"}
